// Limpia el mail, oculta datos sensibles ANTES de mandarlo a la IA y marca riesgos con reglas.
// Las reglas no dependen del modelo: son deterministas y siempre se aplican.
const REGLAS = [
  ['legal',     /abogad|denuncia|defensa del consumidor|carta documento|demanda|juicio|lawyer|legal action|sue you/i],
  ['amenaza',   /te voy a|los voy a|van a ver|se van a arrepentir|escrache/i],
  ['inyeccion', /ignor[aáe]\w*\s+(todas\s+)?(tus|las|sus)?\s*instrucciones|ignore (all |previous |your )?instructions|system prompt|actu[aá] como|act as/i],
];

const TARJETA = /\b(?:\d[ -]?){13,19}\b/g;
const CLAVE = /(contraseña|password|clave|pin|cvv|c[oó]digo de seguridad)\s*[:=]?\s*\S+/gi;

const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  const original = String(j.mensaje || '').replace(/\r/g, '').trim().slice(0, 4000);
  if (!j.id || !original) continue;

  const flags = REGLAS.filter(([, re]) => re.test(`${j.asunto} ${original}`)).map(([f]) => f);

  let mensaje = original.replace(TARJETA, '[TARJETA OCULTA]').replace(CLAVE, '$1: [OCULTO]');
  if (mensaje !== original) flags.push('datos_sensibles');

  salida.push({ json: {
    id: String(j.id),
    remitente: String(j.remitente || '').trim().toLowerCase(),
    asunto: String(j.asunto || '(sin asunto)').trim().slice(0, 200),
    mensaje,
    recibido: j.recibido || new Date().toISOString(),
    flags_regla: flags,
  }});
}
return salida.length ? salida : [{ json: { vacio: true } }];

// Descarta los mails que ya están en la base, para no procesarlos ni cobrar la IA dos veces.
const registrados = new Set($input.all().map(i => String(i.json.id || '')).filter(Boolean));
const nuevos = $('Normalizar y proteger').all()
  .filter(i => !i.json.vacio && !registrados.has(i.json.id));
return nuevos.length ? nuevos : [{ json: { vacio: true } }];

// Valida lo que devolvió la IA y decide el estado con reglas en código, no en el prompt:
// el modelo no es determinista, así que las decisiones de riesgo no pueden depender de él.
const cfg = $('Configuración').first().json;
const mails = $('Quitar ya registrados').all();
const respuestas = $input.all();

const CATEGORIAS = ['consulta', 'reclamo', 'cambio_devolucion', 'facturacion', 'spam', 'otro'];
const URGENCIAS = ['alta', 'media', 'baja'];
const FLAGS_VALIDOS = ['legal', 'datos_sensibles', 'inyeccion', 'amenaza', 'enojo', 'promesa'];
const SENSIBLES = ['legal', 'datos_sensibles', 'inyeccion', 'amenaza', 'promesa'];

// Promesas que el borrador nunca debería hacer sin revisión humana.
const PROMESA = /reembols|reintegr|devolv\w* (el|tu|su) dinero|devoluci[oó]n del dinero|descuento|bonificaci|gratis|sin cargo|sin costo|compensaci|te regalamos|refund|discount|free of charge/i;
const TARJETA = /\b(?:\d[ -]?){13,19}\b/;

function leerJson(r) {
  let texto = r.output?.[0]?.content?.[0]?.text ?? r.message?.content ?? r.text ?? r.output ?? '';
  if (typeof texto !== 'string') texto = JSON.stringify(texto);
  texto = texto.replace(/```json|```/g, '').trim();
  try { return JSON.parse(texto); } catch (e) { return null; }
}

const salida = [];
for (let i = 0; i < mails.length; i++) {
  const m = mails[i].json;
  const ia = leerJson(respuestas[i]?.json || {});

  const base = {
    id: m.id, remitente: m.remitente, asunto: m.asunto, mensaje: m.mensaje, recibido: m.recibido,
  };

  if (!ia) {
    salida.push({ json: { ...base, categoria: 'otro', urgencia: 'alta', resumen: '', flags: m.flags_regla.join(', '),
      borrador: '', respuesta_final: '', prioridad: 'alta', estado: 'pendiente',
      motivo: 'La IA no devolvió un JSON válido: responder a mano' } });
    continue;
  }

  const categoria = CATEGORIAS.includes(ia.categoria) ? ia.categoria : 'otro';
  const urgencia = URGENCIAS.includes(ia.urgencia) ? ia.urgencia : 'media';
  let respuesta = String(ia.respuesta || '').trim().slice(0, 3500);

  const flags = new Set([...m.flags_regla, ...[].concat(ia.flags || []).filter(f => FLAGS_VALIDOS.includes(f))]);
  if (PROMESA.test(respuesta)) flags.add('promesa');
  if (TARJETA.test(respuesta)) { flags.add('datos_sensibles'); respuesta = respuesta.replace(/\b(?:\d[ -]?){13,19}\b/g, '[OCULTO]'); }

  const sensible = [...flags].some(f => SENSIBLES.includes(f));
  let estado = 'pendiente';
  let motivo = String(ia.motivo || '').trim();

  if (categoria === 'spam') { estado = 'descartado'; respuesta = ''; motivo = 'Spam o publicidad'; }
  else if (!respuesta) motivo = 'La IA no redactó respuesta: escribirla a mano';

  const prioridad = (urgencia === 'alta' || sensible) ? 'alta' : urgencia === 'baja' ? 'baja' : 'media';

  salida.push({ json: {
    ...base,
    categoria,
    urgencia,
    resumen: String(ia.resumen || '').trim().slice(0, 300),
    flags: [...flags].join(', '),
    borrador: respuesta,
    respuesta_final: respuesta ? `${respuesta}\n\n${cfg.firma}` : '',
    prioridad,
    estado,
    motivo,
  }});
}
return salida;

// Arma la fila para la planilla de revisión, con las columnas en el orden de la hoja.
const ORDEN = { alta: 0, media: 1, baja: 2 };
return $input.all()
  .map(i => i.json)
  .sort((a, b) => ORDEN[a.prioridad] - ORDEN[b.prioridad])
  .map(j => ({ json: {
    id: j.id,
    prioridad: j.prioridad,
    categoria: j.categoria,
    remitente: j.remitente,
    asunto: j.asunto,
    mensaje: j.mensaje,
    resumen: j.resumen,
    flags: j.flags,
    motivo: j.motivo,
    respuesta_final: j.respuesta_final,
    decision: 'Pendiente',
    procesado: '',
  }}));

// Toma las filas con una decisión nueva y valida que se puedan aplicar.
// Un mail con marcas sensibles no se puede aprobar sin confirmar que se revisó.
const DECISIONES = {
  'aprobar': 'aprobado',
  'aprobar (revisado)': 'aprobado',
  'escalar': 'escalado',
  'descartar': 'descartado',
};
const SENSIBLES = ['legal', 'datos_sensibles', 'inyeccion', 'amenaza', 'promesa'];
const PROMESA = /reembols|reintegr|devolv\w* (el|tu|su) dinero|devoluci[oó]n del dinero|descuento|bonificaci|gratis|sin cargo|sin costo|compensaci|te regalamos|refund|discount|free of charge/i;

const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  const decision = String(j.decision || '').trim().toLowerCase();
  if (!j.id || !decision || decision === 'pendiente' || String(j.procesado || '').trim()) continue;

  const error = motivo => salida.push({ json: { ok: false, id: j.id, procesado: `ERROR: ${motivo}` } });

  const estado = DECISIONES[decision];
  if (!estado) { error(`decisión "${j.decision}" no válida`); continue; }

  const respuesta = String(j.respuesta_final || '').trim();
  const revisado = decision === 'aprobar (revisado)';
  const flags = String(j.flags || '').split(',').map(f => f.trim()).filter(Boolean);
  const sensibles = flags.filter(f => SENSIBLES.includes(f));

  if (estado === 'aprobado') {
    if (!respuesta) { error('la respuesta está vacía'); continue; }
    if (respuesta.length > 4000) { error('la respuesta supera los 4000 caracteres'); continue; }
    if (sensibles.length && !revisado) { error(`tiene marcas sensibles (${sensibles.join(', ')}): revisá y elegí "Aprobar (revisado)"`); continue; }
    if (PROMESA.test(respuesta) && !revisado) { error('la respuesta promete reembolsos, descuentos o algo gratis: revisá y elegí "Aprobar (revisado)"'); continue; }
  }

  salida.push({ json: {
    ok: true,
    id: j.id,
    estado,
    decision: j.decision,
    respuesta_final: respuesta,
    decidido_at: new Date().toISOString(),
  }});
}
return salida.length ? salida : [{ json: { ok: false, vacio: true } }];

// El nodo de Gmail devuelve los datos del envío, no los del mail original:
// se recuperan por posición (Gmail procesa los items en el mismo orden en que llegan).
const aprobados = $('¿Responder?').all(0);
return $input.all().map((r, i) => ({ json: {
  id: aprobados[i].json.id,
  estado: 'respondido',
  respondido_at: new Date().toISOString(),
}}));

// Texto que queda en la columna "procesado" de la planilla.
const fecha = new Date().toLocaleString('es-AR', {
  timeZone: 'America/Argentina/Buenos_Aires',
  day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit',
});
return $input.all()
  .filter(i => i.json.id)
  .map(i => ({ json: { id: i.json.id, procesado: `${fecha} · ${i.json.estado}` } }));

// Las filas que no se pudieron aplicar vuelven a la planilla con el motivo del error.
return $input.all()
  .filter(i => i.json.id && !i.json.vacio)
  .map(i => ({ json: { id: i.json.id, procesado: i.json.procesado } }));
